sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Malý poster – ako v Table Search */
.movie-poster img {
    width: 150px;      /* nastavíš podľa potreby */
    height: auto;       /* zachová proporcie */
    border-radius: 6px; /* pekný zaoblený roh */
    box-shadow: 0 2px 6px rgba(0,0,0,0.3); /* jemný tieň */
    display: block;
    margin: 0 auto;    /* centrovanie v kolónke */
}

/* Odstrániť pôvodný hero styling */
.movie-poster-tmdb {
    display: none !important;
}

.movie-cast-section {
    margin-top: 20px;
}

.movie-cast-list {
    display: flex;
    gap: 16px;
    overflow-x: auto;
    padding-bottom: 10px;
}

.movie-cast-card {
    min-width: 140px;
    max-width: 140px;
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
    flex-shrink: 0;
}

.movie-cast-card img {
    width: 100%;
    height: 180px;
    object-fit: cover;
    display: block;
}

.movie-cast-info {
    padding: 10px;
}

.movie-cast-name {
    font-weight: 600;
    margin-bottom: 6px;
}

.movie-cast-role {
    font-size: 13px;
    color: #666;
}

.movie-crew-section {
    display: flex;
    gap: 40px;
    margin: 20px 0;
    flex-wrap: wrap;
}

.movie-crew-name {
    font-weight: 600;
}

.movie-crew-role {
    font-size: 13px;
    color: #666;
}

sp_widget.script:
(function() {

    var sysId = $sp.getParameter('sys_id');
    if (!sysId)
        return;

    var gr = new GlideRecord('x_1080820_mvx_movie');
    if (!gr.get(sysId))
        return;

    data.movie = {
        title: gr.getValue('title'),
        originalTitle: gr.getValue('original_title'),
        festivalTitle: gr.getValue('festival_title'),
        releaseDate: gr.getValue('release_date'),
        description: gr.getValue('description'),
        posterUrl: gr.getValue('poster_url'),
        tmdbId: gr.getValue('tmdb_id'),
        genres: [],
        actors: [],
        directors: []
    };

    var grg = new GlideRecord('x_1080820_mvx_movie_genre');
    grg.addQuery('movie_ref', sysId);
    grg.query();

    while (grg.next()) {
        data.movie.genres.push(grg.getDisplayValue('genre_ref'));
    }

    var gra = new GlideRecord('x_1080820_mvx_movie_actor');
    gra.addQuery('movie_ref', sysId);
    gra.setLimit(10);
    gra.query();

    while (gra.next()) {
        data.movie.actors.push({
            name: gra.getDisplayValue('actor_ref'),
            role: gra.getValue('role_name'),
            photo: gra.actor_ref.profile_url + ''
        });
    }

    var grd = new GlideRecord('x_1080820_mvx_movie_director');
    grd.addQuery('movie_ref', sysId);
    grd.query();

    while (grd.next()) {
        data.movie.directors.push({
            name: grd.getDisplayValue('director_ref')
        });
    }

})();
